TWComponent.script:
tw.local.sql = "SELECT BILLOFLADINGREF, BILLOFLADINGDATE, REQUESRID, ID FROM "+tw.env.LKP_DB_Schema+".odc_bills where requesrid = ?";

tw.local.sqlParameters = new tw.object.listOf.SQLParameter();
tw.local.sqlParameters[0] =  new tw.object.SQLParameter();
tw.local.sqlParameters[0].value = tw.local.requestId;

//tw.local.odcRequest = {};
//tw.local.odcRequest.BasicDetails ={};
tw.local.odcRequest.BasicDetails.Bills = new tw.object.listOf.Bills();

if(tw.local.sqlResults.listLength > 0)
{
	for(var i =0; i<tw.local.sqlResults[0].rows.listLength ; i++)
	{
		tw.local.odcRequest.BasicDetails.Bills[i]    			 = new tw.object.Bills();
		tw.local.odcRequest.BasicDetails.Bills[i].billOfLadingDate   = tw.local.sqlResults[0].rows[i].data[1];
		tw.local.odcRequest.BasicDetails.Bills[i].billOfLadingRef    = tw.local.sqlResults[0].rows[i].data[0];
	}

}

ns16:scriptTask.ns16:script:
tw.local.sql = "SELECT BILLOFLADINGREF, BILLOFLADINGDATE, REQUESRID, ID FROM "+tw.env.LKP_DB_Schema+".odc_bills where requesrid = ?";

tw.local.sqlParameters = new tw.object.listOf.SQLParameter();
tw.local.sqlParameters[0] =  new tw.object.SQLParameter();
tw.local.sqlParameters[0].value = tw.local.requestId;

//tw.local.odcRequest = {};
//tw.local.odcRequest.BasicDetails ={};
tw.local.odcRequest.BasicDetails.Bills = new tw.object.listOf.Bills();

if(tw.local.sqlResults.listLength > 0)
{
	for(var i =0; i<tw.local.sqlResults[0].rows.listLength ; i++)
	{
		tw.local.odcRequest.BasicDetails.Bills[i]    			 = new tw.object.Bills();
		tw.local.odcRequest.BasicDetails.Bills[i].billOfLadingDate   = tw.local.sqlResults[0].rows[i].data[1];
		tw.local.odcRequest.BasicDetails.Bills[i].billOfLadingRef    = tw.local.sqlResults[0].rows[i].data[0];
	}

}
